/**
 * @file test-certificates.mjs
 * @description End-to-end test for the LearnX Certificates & Course Completion
 * feature (roadmap #7).
 *
 * Covers:
 *   1. Completion is detected at 100% and enrollment => COMPLETED.
 *   2. A certificate is AUTO-generated by the progress hook on first completion.
 *   3. Certificate has a unique human-friendly number (LRNX-XXXX...).
 *   4. generateCertificate is idempotent (no duplicate per student+course).
 *   5. getMyCertificates returns the issued certificate.
 *   6. getCertificate enforces visibility (owner OK, other student 403).
 *   7. verifyCertificate returns valid for the real number & invalid for a bogus one.
 *
 * Run from backend folder:  node scripts/test-certificates.mjs
 */

import mongoose from "mongoose";
import dotenv from "dotenv";

import courseService from "../src/services/course.service.js";
import { createModule, publishModule } from "../src/services/module.service.js";
import { createLesson, publishLesson } from "../src/services/lesson.service.js";
import { enrollStudent } from "../src/services/enrollment.service.js";
import { updateLessonProgress } from "../src/services/progress.service.js";
import certificateService from "../src/services/certificate.service.js";
import Certificate from "../src/models/certificate.model.js";
import Progress from "../src/models/progress.model.js";
import Enrollment from "../src/models/enrollment.model.js";
import { ENROLLMENT_STATUS } from "../src/constants/enrollment.constants.js";
import { CERTIFICATE_STATUS, CERTIFICATE_NUMBER_PREFIX } from "../src/constants/certificate.constants.js";

dotenv.config();

let pass = 0, fail = 0;
const ok = (cond, label) => {
  if (cond) { pass++; console.log(`  ✅ ${label}`); }
  else { fail++; console.log(`  ❌ ${label}`); }
};

const uri = process.env.MONGODB_URI;
if (!uri) {
  console.error("MONGODB_URI is not set in .env");
  process.exit(1);
}

const title = `Certificate Test Course ${Date.now()}`;

try {
  await mongoose.connect(uri);
  const db = mongoose.connection.db;

  // 1. Instructor + student + a second student (for access-control checks)
  const instructor = await db.collection("users").findOne({ role: "instructor" });
  if (!instructor) { console.error("No instructor found."); process.exit(1); }
  const student = await db.collection("users").findOne({ role: "student" });
  if (!student) { console.error("No student found."); process.exit(1); }
  let other = await db.collection("users").findOne({ role: "student", _id: { $ne: student._id } });
  if (!other) {
    other = await db.collection("users").findOne({ role: "student" }); // fallback: same student
  }

  const instructorAuth = { _id: instructor._id, role: instructor.role };

  // 2. Category
  let category = await db.collection("categories").findOne({});
  if (!category) {
    const ins = await db.collection("categories").insertOne({ name: "Programming", slug: "programming", createdAt: new Date(), updatedAt: new Date() });
    category = { _id: ins.insertedId };
  }

  // 3. Course
  const course = await courseService.createCourse(
    {
      title,
      shortDescription: "Certificate feature end-to-end test course.",
      description: "Test course used to verify certificates are generated at 100% completion.",
      pricing: { price: 19.99 },
      courseLanguage: "English",
      category: category._id,
      thumbnail: { publicId: "seed/cert-test", url: "https://images.unsplash.com/photo-1516321318423-f06f85e504b3" },
    },
    instructorAuth
  );
  await courseService.publishCourse(course._id, instructorAuth);

  // 4. Module + 1 lesson (so 1 lesson = 100% completion)
  const module = await createModule({ course: course._id, title: "Module 1", description: "m1", isPreview: true }, instructorAuth);
  await publishModule(module._id, instructorAuth);
  const lesson = await createLesson(
    {
      module: module._id,
      title: "Lesson 1",
      description: "l1",
      lessonType: "VIDEO",
      content: { type: "VIDEO", video: { url: "https://example.com/cert.mp4", duration: 300, provider: "YOUTUBE", allowDownload: false } },
      duration: 300,
      isPreview: true,
      isLocked: false,
    },
    instructorAuth
  );
  await publishLesson(lesson._id, instructorAuth);

  // 5. Enroll student (creates Progress)
  const enroll = await enrollStudent({ courseId: course._id, studentId: student._id });
  ok(Boolean(enroll.enrollment && enroll.progress), "Enrollment + Progress created");

  // 6. Complete the single lesson -> 100% -> should auto-generate certificate
  const progress = await updateLessonProgress({ lessonId: lesson._id, studentId: student._id, completed: true });

  console.log("\n== 1. Completion detection ==");
  ok(progress.completionPercentage === 100, "completionPercentage === 100");
  ok(progress.isCourseCompleted === true, "isCourseCompleted === true");

  const enrollmentDoc = await Enrollment.findById(enroll.enrollment._id).lean();
  ok(enrollmentDoc.status === ENROLLMENT_STATUS.COMPLETED, `Enrollment status COMPLETED (got ${enrollmentDoc.status})`);

  console.log("\n== 2. Auto-generated certificate (via progress hook) ==");
  const cert = await Certificate.findOne({ student: student._id, course: course._id }).lean();
  ok(Boolean(cert), "Certificate was auto-generated on completion");
  if (cert) {
    ok(cert.certificateNumber.startsWith(`${CERTIFICATE_NUMBER_PREFIX}-`), `Number has ${CERTIFICATE_NUMBER_PREFIX}- prefix: ${cert.certificateNumber}`);
    ok(cert.certificateNumber.length > CERTIFICATE_NUMBER_PREFIX.length + 2, "Number is long enough to be unique");
    ok(cert.status === CERTIFICATE_STATUS.ISSUED, "Certificate status ISSUED");
    ok(cert.issueSnapshot && cert.issueSnapshot.courseTitle === course.title, "Issue snapshot stores course title");
    ok(cert.enrollment.toString() === enroll.enrollment._id.toString(), "Certificate references enrollment");
    ok(cert.fingerprint && cert.fingerprint.length === 64, "Fingerprint is a sha256 hex (64 chars)");
  }

  console.log("\n== 3. generateCertificate is idempotent ==");
  const again = await certificateService.generateCertificate({ enrollmentId: enroll.enrollment._id, studentId: student._id });
  ok(again._id.toString() === cert._id.toString(), "Re-generate returns the SAME certificate (no duplicate)");
  const certCount = await Certificate.countDocuments({ student: student._id, course: course._id });
  ok(certCount === 1, `Exactly one certificate per student+course (count=${certCount})`);

  console.log("\n== 4. getMyCertificates ==");
  const mine = await certificateService.getMyCertificates({ studentId: student._id });
  ok(mine.certificates.length >= 1, "Student's certificate list is non-empty");
  ok(mine.certificates[0]._id.toString() === cert._id.toString(), "Issued certificate appears first");

  console.log("\n== 5. getCertificate visibility ==");
  const asOwner = await certificateService.getCertificate({ certificateId: cert._id, user: { _id: student._id, role: "student" } });
  ok(asOwner._id.toString() === cert._id.toString(), "Owner can read certificate");
  if (!other || other._id.toString() === student._id.toString()) {
    console.log("  (skipping 403-for-other: no second distinct student available)");
  } else {
    let forbidden = false;
    try {
      await certificateService.getCertificate({ certificateId: cert._id, user: { _id: other._id, role: "student" } });
    } catch (e) {
      forbidden = String(e.statusCode) === "403" || /allow|forbidden/i.test(e.message);
    }
    ok(forbidden, "Another student is forbidden (403) from reading it");
  }

  console.log("\n== 6. verifyCertificate (public) ==");
  const verifyResult = await certificateService.verifyCertificate({ certificateNumber: cert.certificateNumber });
  ok(verifyResult.valid === true, "Real number verifies as valid");
  ok(verifyResult.studentName.length > 0, "Returns student name");
  ok(verifyResult.course === course.title, "Returns course title");

  let bogusThrew = false;
  try {
    await certificateService.verifyCertificate({ certificateNumber: "LRNX-BOGUS0000" });
  } catch (e) {
    bogusThrew = /not found/i.test(e.message);
  }
  ok(bogusThrew, "Bogus number throws NotFound");

  console.log(`\nRESULT: ${pass} passed, ${fail} failed`);
  await mongoose.disconnect();
  process.exit(fail ? 1 : 0);
} catch (err) {
  console.error("Error:", err);
  await mongoose.disconnect();
  process.exit(1);
}
